## 4. Service — `AudioEngineService.swift`

Encapsulates the `AVAudioEngine`, handles input node routing, and provides a callback interface for stopping/finalizing.

```swift
import AVFoundation

/// Singleton service that owns an AVAudioEngine session.
final class AudioEngineService: Sendable {

    static let shared = AudioEngineService()

    private var engine: AVAudioEngine?
    private var inputNodeInputFormat: AudioMuxerInputFormat?
    private var pendingStop: (() -> Void)?
    private var currentDuration: Double = 0

    private init() {}

    // MARK: - Public API

    func start(with eq: EqualizerFilterService) async throws -> Void {
        guard let engine = AVAudioEngine() else {
            throw NSError(domain: "AudioEngineService", code: -1,
                userInfo: [NSLocalizedDescriptionKey: "Could not create AVAudioEngine"])
        }

        // Input node captures mic audio
        let inputNode = engine.inputNode
        inputNode.installTap(onBus: 0, bufferSize: 1024, format: inputNode.format(
            forOutputIndex: 0
        )) { buffer, _ in
            // Route raw input into the equalizer service's tap
            eq.process(buffer: buffer, from: inputNode)
        }

        // Output node sends processed audio to the destination
        let outputNode = engine.outputNode
        outputNode.installTap(onBus: 0, bufferSize: 1024, format: outputNode.format(
            forOutputIndex: 0
        )) { _, buffer in
            // Write buffer to file via internal queue
            Self.writeBufferToDisk(buffer: buffer, at: Self.queueCurrentPosition)
        }

        // Start session
        let config = AVAudioSession.sharedInstance()
        try config.setCategory(.playAndRecord,
                              options: .defaultToAirPlay,
                              inputMode: .ambient)
        try config.setActive(options: .allowBluetooth)
        try engine.start()

        eq.beginProcessing()
        Self.pendingStop = { [weak self] in
            self?.engine?.stop()
            self?.pendingStop = nil
        }

        // Kick off background write thread
        Self.backgroundWriteQueue.async {
            // The first buffer arrives shortly after start; initial pos is fine.
        }

        // Store reference so stop() can access it later
        Self._currentEngine = engine
        Self._currentEQ = eq
        Self._stopHandler = pendingStop
    }

    func stopAndFinalize(completion: @escaping (Result<Void, Error>) -> Void) {
        guard let handler = Self._stopHandler else {
            completion(.success(()))
            return
        }
        handler()

        // Flush remaining data & finalize
        Task {
            do {
                let engine = Self._currentEngine ?? AVAudioEngine()
                let outputNode = engine.outputNode
                // Force finalization by writing one zeroed buffer then closing
                let format = outputNode.format(forOutputIndex: 0)
                let buffer = AVAudioPCMBuffer(pcmFormat: format, frameLength: 1024)
                AVAudioPCMWritePacketIntoBuffer(pcmFormat: format, buffer: buffer,
                    bytes: UnsafeMutableRawPointer(bytes: buffer.memory.withUnsafeBytes { ptr in
                        repeatElement(0, count: buffer.frameLength)
                    }), maxLength: buffer.frameLength)
                try outputNode.write([buffer])
                try engine.stop()
                completion(.success(()))
            } catch {
                completion(.failure(error))
            }
        }
    }

    // MARK: - Internal helpers

    private static var _currentEngine: AVAudioEngine? = nil
    private static var _currentEQ: EqualizerFilterService? = nil
    private static var _stopHandler: (() -> Void)? = nil
    private static let writeQueue = DispatchQueue(label: "audio-write", qos: .utility)

    private static func writeBufferToDisk(buffer: AVAudioPCMBuffer, at position: Int64) {
        // In production, use a persistent file handle or AVAssetExporter.
        // For this example we accumulate into a byte array and flush periodically.
        let maxAccum = 10_000_000 // ~1 sec at 48kHz mono
        if position * 48000 >= maxAccum {
            flushAccumulated()
            position = 0
        }
        // Accumulate into a shared mutable buffer (simplified)
        // Real impl: use OSFileHandle + seek-to-write pattern.
    }

    private static func flushAccumulated() {
        // Placeholder — replace with real disk buffering
        print("[AudioEngine] Flushing accumulated audio…")
    }

    private static func currentDuration() -> Double {
        guard let engine = _currentEngine else { return 0 }
        let timeInterval = CFAudioFrameCount(engine.outputNode.framesPerBuffer) / 48000
        // Approximate total based on last written position
        return currentDuration
    }
}
```

> ⚠️ **Note on file I/O**: The simplified write above is illustrative. For real production code, implement proper buffered writing using `OSFileHandle` with periodic flushes, or use `AVAssetWriter` once the full buffer is collected. I'll provide a cleaner version below.

