## 5. Service — `EqualizerFilterService.swift`

Applies per-band gains to the incoming PCM buffer and routes back through the engine's input tap.

```swift
import AVFoundation

/// Manages EQ filters applied to the mic signal before it reaches the output.
final class EqualizerFilterService: Sendable {

    struct EqualizerBand: Hashable, Equatable {
        let frequency: Double       // Hz
        let gainDB: Double          // dB
        let type: FilterType

        enum FilterType: String, CaseIterable {
            case peq = "PEQ"         // Peak EQ (bump/cut)
            case shel = "Shelf"      // Low/high shelf
            case notch = "Notch"     // Narrow cut
        }
    }

    private let engine: AudioEngineService
    private var taps: [[EqualizerBand, AVAudioUnitFilterParameters]] = []
    private var processingStarted = false

    init(engine: AudioEngineService) {
        self.engine = engine
    }

    // MARK: - Public API

    func beginProcessing() {
        processingStarted = true
        buildFilters()
    }

    func process(buffer: AVAudioPCMBuffer, from inputNode: AVAudioInputNode) {
        guard processingStarted else { return }

        // Insert each EQ band as a PEQ filter chain before the output
        // We simulate EQ by modulating gain in bands via dynamic gain nodes.
        // For a real implementation, insert AVAudioUnitPEQ per band.
        applyBandGains(to: buffer, bands: equalizerBands)
    }

    deinit {
        processingStarted = false
    }

    // MARK: - EQ Band Management

    var equalizerBands: [EqualizerBand] {
        get {
            // Mirror the bands from RecordingState if accessible, otherwise defaults
            return [
                EqualizerBand(frequency: 20,  gainDB: 0.0,  type: .peq),
                EqualizerBand(frequency: 40,  gainDB: 0.0,  type: .peq),
                EqualizerBand(frequency: 80,  gainDB: 0.0,  type: .peq),
                EqualizerBand(frequency: 125, gainDB: 0.0,  type: .peq),
                EqualizerBand(frequency: 250, gainDB: 0.0,  type: .peq),
                EqualizerBand(frequency: 500, gainDB: 0.0,  type: .peq),
                EqualizerBand(frequency: 1000, gainDB: 0.0, type: .peq),
                EqualizerBand(frequency: 2500, gainDB: 0.0, type: .peq),
                EqualizerBand(frequency: 5000, gainDB: 0.0, type: .peq),
                EqualizerBand(frequency: 10000, gainDB: 0.0, type: .peq),
            ]
        }
        set {
            taps = newValue.map { band in
                let params = AVAudioUnitPEQParameters()
                params.frequency.value = band.frequency
                params.Q.value = 1.0
                params.gain.value = exp(band.gainDB * 0.05) // linear approx
                return (band, params)
            }
        }
    }

    /// Applies simulated band gains directly to the PCM buffer.
    /// This is a lightweight approach; for true filtering, insert AVAudioUnitPEQ
    /// nodes inside the engine's input bus tap.
    private func applyBandGains(to buffer: AVAudioPCMBuffer, bands: [EqualizerBand]) {
        // Simple amplitude modulation per band using FFT-based approach
