    @MainActor
    private func checkMicrophonePermission() {
        #if os(iOS)
        let status = AVAudioEnvironment().recordPermission
        if status == .notDetermined {
            AsyncUIActivity.request(record: true).then { activity in
                if activity.isCancelled { return }
                switch activity.result {
                case .restricted:
                    // Cannot record — show message
                    break
                case .denied:
                    state.error = "Microphone access denied."
                    break
                case .granted:
                    // Proceed to start recording
                    break
                @unknown default: break
                }
            }
        }
        #endif
    }

    @MainActor
    private func performStartRecording() {
        Task {
            do {
                try await state.startRecording(outputPath: nil)
