## 7. View — `EqualizerOverlayView.swift`

A live-frequency-bar visualizer rendered on canvas, showing which bands are "active" (loudest moments).

```swift
import SwiftUI
import CoreGraphics

struct EqualizerOverlayView: View {

    let bands: [EqualizerBand]
    let isLive: Bool
    let onBandChange: ([EqualizerBand]) -> Void

    // Simulated amplitude per band (in real app, read from DSP analysis)
    private var bandLevels: [Double] = Array(repeating: 0.3, count: bands.count)

    var body: some View {
        GeometryReader { geo in
            Canvas { context, size in
                let w = size.width
                let h = size.height
                let n = bands.count
                let step = h / Double(n)

                // Background
                context.stroke(CGRect(x: 0, y: 0, width: w, height: h),
                               with: .clear, style: .strokePath)

                // Bars
                for i in 0..<n {
                    let level = bandLevels[i]
                    let barHeight = step * (level / 1.0)
                    let y = h - barHeight

                    let color = HSLColor(
                        hue: Double(i) / Double(n - 1) * 360,
                        saturation: 0.7,
                        lightness: 0.35 + Double(level) * 0.25
                    ).cgColor

                    context.fill(CGRect(
                        x: (w - w * Double(barHeight / step)) / 2,
                        y: y,
                        width: w * Double(barHeight / step) / max(1, n),
                        height: barHeight
                    ), with: color, style: .fill)

                    // Labels
                    let freqLabel = bands[i].frequency
                    let lbl = Text(String(format: "%.0f kHz",
                       freqLabel < 1000 ? freqLabel : freqLabel / 1000))
                        .font(.caption2.monospacedDigit().italic())
                        .foregroundStyle(.white.opacity(0.8))
                        .offset(y: -step * 0.55)
                    lbl.draw(at: CGPoint(x: w / 2, y: h - step * 0.5))
                        .anchorX(.center)
                }
            }
            .frame(height: 180)
            .background(.black.opacity(0.6))
            .clipShape(RoundedRectangle(cornerRadius: 12))
        }
        .onAppear {
            // In production, wire up real FFT analysis from the engine
            // to update bandLevels continuously.
        }
    }
}

// MARK: - Preview
#Preview {
    EqualizerOverlayView(
        bands: VoiceRecorderView.defaultBands(),
