	public static void main(String[] args) {
		boolean run = true;
		Scanner scan = new Scanner(System.in);

		BigInteger balance = BigInteger.ZERO;

		while (run) {
			System.out.println("-----------------------------");
			System.out.println("1.예금 | 2.출금 | 3.잔고 | 4.종료");
			System.out.println("-----------------------------");
			System.out.print("선택> ");

			String menuChoice = scan.nextLine(); // 메뉴 선택값 읽음

			if (menuChoice.isEmpty()) continue; // 빈 입력 시 다시 요청

			switch (menuChoice.trim()) {
				case "1":
					try {
						System.out.print("예금액> ");
						String depositStr = scan.nextLine().trim();
						BigInteger deposit = new BigInteger(depositStr);

						if (deposit.compareTo(BigInteger.ZERO) > 0) {
							balance = balance.add(deposit);
							System.out.println("예금이 성공적으로 등록되었습니다.");
						} else {
							System.out.println("올바른 값을 입력하시오.");
						}
					} catch (NumberFormatException e) {
						System.out.println("숫자로 입력하시오.");
					}
					break;

				case "2":
					try {
						System.out.print("출금액> ");
						String withdrawStr = scan.nextLine().trim();
						BigInteger withdraw = new BigInteger(withdrawStr);

						if (withdraw.compareTo(BigInteger.ZERO) > 0 
								&& withdraw.compareTo(balance) <= 0) {
							balance = balance.subtract(withdraw);
							System.out.println("출금이 성공적으로 처리되었습니다.");
						} else {
							System.out.println("잔액이 부족합니다 혹은 잘못된 입력입니다.");
						}
					} catch (NumberFormatException e) {
						System.out.println("숫자로 입력하시오.");
					}
					break;

				case "3":
					System.out.println("잔고>" + balance);
					break;

				case "4":
					run = false;
					break;

				default:
					System.out.println("1, 2, 3, 4 중 하나로 입력하시오.");
					break;
			}
			System.out.println();
		}

		System.out.println("\n프로그램 종료");
		scan.close();
	}
